"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import domainPacks from "@/config/domain-packs.json";
import contentFormats from "@/config/content-formats.json";
import editStyles from "@/config/edit-styles-v2.json";
import { recommendedStyleIds } from "@/lib/domain-engine";
import styles from "./studio.module.css";
import extra from "./advanced.module.css";

const Icon = ({name}) => {
  const paths={spark:<path d="m12 3-1.2 4.1A5.5 5.5 0 0 1 7.1 11L3 12l4.1 1.2a5.5 5.5 0 0 1 3.7 3.7L12 21l1.2-4.1a5.5 5.5 0 0 1 3.7-3.7L21 12l-4.1-1.2a5.5 5.5 0 0 1-3.7-3.7Z"/>,check:<path d="m5 12 4 4L19 6"/>,arrow:<path d="m9 18 6-6-6-6"/>,download:<><path d="M12 3v12m0 0 4-4m-4 4-4-4"/><path d="M5 20h14"/></>,search:<><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>};
  return <svg aria-hidden="true" width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{paths[name]}</svg>;
};

const initialScript={hook:"Nếu nội dung của bạn giống mọi người, có thể vấn đề nằm ở cách bạn chứng minh.",body:"Chọn một ngành, nguồn research và format để BrandFlow tạo kịch bản phù hợp với khách hàng, loại bằng chứng và ràng buộc của ngành đó.",cta:"Lưu lại nếu bạn muốn biến chuyên môn thành một hệ thống nội dung."};

export default function MultiNicheStudio(){
  const [domainId,setDomainId]=useState("finance");
  const [formatId,setFormatId]=useState("evidence-explainer");
  const domain=useMemo(()=>domainPacks.find(x=>x.id===domainId)||domainPacks[0],[domainId]);
  const format=useMemo(()=>contentFormats.find(x=>x.id===formatId)||contentFormats[0],[formatId]);
  const recommended=useMemo(()=>recommendedStyleIds(domainId,formatId),[domainId,formatId]);
  const [brand,setBrand]=useState({name:"SFI Academy",niche:"tài chính, đầu tư và quản lý tiền",audience:"người đi làm muốn hiểu và quản lý tài chính có hệ thống",voice:"Điềm tĩnh, chính xác, giải thích bằng dữ liệu"});
  const [styleId,setStyleId]=useState("editorial-proof");
  const [videoMode,setVideoMode]=useState("avatar");
  const [script,setScript]=useState(initialScript);
  const [scriptCandidates,setScriptCandidates]=useState([]);
  const [trends,setTrends]=useState([]);
  const [selectedTrend,setSelectedTrend]=useState(null);
  const [approvals,setApprovals]=useState({researchApproved:false,scriptApproved:false});
  const [busy,setBusy]=useState("");
  const [job,setJob]=useState(null);
  const [notice,setNotice]=useState("Demo mode không gọi API trả phí.");
  const [systemStatus,setSystemStatus]=useState({mode:"demo",services:{research:{configured:false},script:{configured:false},avatar:{configured:false}}});
  const [hydrated,setHydrated]=useState(false);
  const previousBrand=useRef(null);
  const selectedStyle=editStyles.find(x=>x.id===styleId)||editStyles[0];

  useEffect(()=>{try{const raw=localStorage.getItem("brandflow-multi-niche-v2");if(raw){const saved=JSON.parse(raw);if(saved.domainId)setDomainId(saved.domainId);if(saved.formatId)setFormatId(saved.formatId);if(saved.brand)setBrand(saved.brand);if(saved.styleId)setStyleId(saved.styleId);if(saved.videoMode)setVideoMode(saved.videoMode);if(saved.script)setScript(saved.script);if(saved.scriptCandidates)setScriptCandidates(saved.scriptCandidates);if(saved.trends)setTrends(saved.trends);if(saved.selectedTrend)setSelectedTrend(saved.selectedTrend);if(saved.approvals)setApprovals(saved.approvals);}}catch{}finally{setHydrated(true);}},[]);
  useEffect(()=>{if(!hydrated)return;localStorage.setItem("brandflow-multi-niche-v2",JSON.stringify({domainId,formatId,brand,styleId,videoMode,script,scriptCandidates,trends,selectedTrend,approvals}));},[hydrated,domainId,formatId,brand,styleId,videoMode,script,scriptCandidates,trends,selectedTrend,approvals]);
  useEffect(()=>{fetch("/api/multi-niche/status").then(response=>response.json()).then(data=>{setSystemStatus(data);if(data.mode!=="demo"){const live=Object.values(data.services).filter(item=>item.configured).map(item=>item.provider).join(", ");setNotice(`Chế độ hybrid: ${live} đã cấu hình. Chỉ bấm chạy khi bạn chấp nhận chi phí API tương ứng.`);}}).catch(()=>{});},[]);
  useEffect(()=>{if(!hydrated)return;const next={name:brand.name,niche:brand.niche,audience:brand.audience,voice:brand.voice};const prev=previousBrand.current;if(!prev){previousBrand.current=next;return;}if(prev.niche!==next.niche){setTrends([]);setSelectedTrend(null);setApprovals({researchApproved:false,scriptApproved:false});setScriptCandidates([]);setJob(null);}else if(prev.name!==next.name||prev.audience!==next.audience||prev.voice!==next.voice){setApprovals(value=>({...value,scriptApproved:false}));setScriptCandidates([]);setJob(null);}previousBrand.current=next;},[hydrated,brand.name,brand.niche,brand.audience,brand.voice]);

  function chooseDomain(id){const next=domainPacks.find(x=>x.id===id)||domainPacks[0];setDomainId(id);setBrand(prev=>({...prev,niche:next.niche,audience:next.audience,voice:next.voice}));setStyleId(next.defaultStyle);setTrends([]);setSelectedTrend(null);setScriptCandidates([]);setApprovals({researchApproved:false,scriptApproved:false});setJob(null);}
  function chooseTrend(item){setSelectedTrend(item);setApprovals(prev=>({...prev,researchApproved:false,scriptApproved:false}));setJob(null);}
  function updateScript(field,value){setScript(prev=>({...prev,[field]:value}));setApprovals(prev=>({...prev,scriptApproved:false}));setJob(null);}

  async function runResearch(){setBusy("research");setNotice("");try{const response=await fetch("/api/research",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({niche:`${brand.niche} ${domain.researchSeeds.join(" ")}`})});const data=await response.json();if(!response.ok)throw new Error(data.error);setTrends(data.items||[]);setSelectedTrend(data.items?.[0]||null);setApprovals({researchApproved:false,scriptApproved:false});setNotice(data.mode==="live"?"Đã lấy dữ liệu research thật. Hãy chọn và duyệt một nguồn.":"Đã tạo bộ research demo, không tiêu tốn credit.");}catch(error){setNotice(error.message||"Không thể research.");}finally{setBusy("");}}
  async function writeScript(){if(!selectedTrend){setNotice("Hãy research và chọn một nguồn trước khi tạo kịch bản.");return;}setBusy("script");setNotice("");try{const response=await fetch("/api/multi-niche/script",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({domainId,formatId,brandName:brand.name,...brand,trendTitle:selectedTrend.title,trendHook:selectedTrend.hook})});const data=await response.json();if(!response.ok)throw new Error(data.error);const candidates=data.candidates||[data];setScriptCandidates(candidates);setScript(candidates[0]);setApprovals(prev=>({...prev,scriptApproved:false}));setJob(null);setNotice(data.sourceMode==="live"?`Đã tạo 3 kịch bản bằng ${data.model}. Hãy chọn và duyệt một bản.`:"Đã tạo 3 kịch bản demo, không tiêu tốn credit. Hãy chọn và duyệt một bản.");}catch(error){setNotice(error.message||"Không thể tạo kịch bản.");}finally{setBusy("");}}
  async function buildManifest(){if(!approvals.researchApproved||!approvals.scriptApproved){setNotice("Cần duyệt nguồn research và kịch bản trước khi tạo manifest.");return;}setBusy("manifest");setNotice("");try{const response=await fetch("/api/multi-niche/pipeline",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({domainId,formatId,brand,script,source:selectedTrend,videoMode,editStyle:selectedStyle,approvals})});const data=await response.json();if(!response.ok)throw new Error(data.error);setJob(data);setNotice("Production manifest v2 đã sẵn sàng. Render trả phí và publishing vẫn đang khóa.");}catch(error){setNotice(error.message||"Không thể tạo manifest.");}finally{setBusy("");}}
  function downloadManifest(){if(!job?.manifest)return;const blob=new Blob([JSON.stringify(job.manifest,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=`${job.jobId.toLowerCase()}-manifest.json`;link.click();URL.revokeObjectURL(url);}

  return <main className={styles.shell}>
    <header className={styles.header}><div className={styles.logo}><span><Icon name="spark"/></span>BrandFlow <b>Multi-Niche</b></div><div className={styles.mode}><i/> {systemStatus.mode==="demo"?"Demo an toàn":"Hybrid · có API live"}</div></header>
    <section className={styles.hero}><div><p>AI VIDEO OPERATING SYSTEM</p><h1>Một agent. Nhiều ngành.<br/><em>Đúng logic từng ngách.</em></h1><span>Finance là chuẩn tham chiếu; domain pack quyết định research, bằng chứng, compliance và phong cách dựng cho từng ngành.</span></div><div className={styles.summary}><small>CẤU HÌNH HIỆN TẠI</small><strong>{domain.name}</strong><span>{format.name} · {selectedStyle.name}</span><div>{domain.proofTypes.map(item=><b key={item}>{item}</b>)}</div></div></section>
    {notice&&<div className={styles.notice} role="status"><Icon name="check"/>{notice}</div>}
    <nav className={extra.progress} aria-label="Tiến độ sản xuất">{[["1","Domain",true],["2","Research",!!selectedTrend],["3","Kịch bản",approvals.scriptApproved],["4","Production",!!job]].map(([n,label,done])=><span key={n} className={done?extra.done:""}><b>{done?<Icon name="check"/>:n}</b>{label}</span>)}</nav>
    <div className={styles.grid}>
      <section className={styles.panel}><Title number="01" title="Chọn domain pack" text="Mỗi ngành có audience, proof và rule an toàn riêng."/><div className={styles.domainGrid}>{domainPacks.map(item=><button key={item.id} aria-pressed={domainId===item.id} className={domainId===item.id?styles.selected:""} onClick={()=>chooseDomain(item.id)}><strong>{item.name}</strong><span>{item.defaultStyle}</span></button>)}</div><div className={styles.formGrid}><Field label="Tên thương hiệu" value={brand.name} onChange={value=>setBrand({...brand,name:value})}/><Field label="Ngách cụ thể" value={brand.niche} onChange={value=>setBrand({...brand,niche:value})}/><Field textarea label="Khán giả" value={brand.audience} onChange={value=>setBrand({...brand,audience:value})}/><Field textarea label="Giọng thương hiệu" value={brand.voice} onChange={value=>setBrand({...brand,voice:value})}/></div><div className={styles.guardrails}><strong>Ràng buộc theo ngành</strong>{domain.compliance.map(item=><span key={item}><Icon name="check"/>{item}</span>)}{domain.disclaimer&&<p>{domain.disclaimer}</p>}</div></section>
      <section className={styles.panel}><Title number="02" title="Chọn format nội dung" text="Cấu trúc kể chuyện quyết định cách giữ người xem."/><div className={styles.formatList}>{contentFormats.map(item=><button key={item.id} aria-pressed={formatId===item.id} className={formatId===item.id?styles.selected:""} onClick={()=>{setFormatId(item.id);setApprovals(prev=>({...prev,scriptApproved:false}));setJob(null);}}><span><strong>{item.name}</strong><small>{item.bestFor}</small></span><Icon name="arrow"/></button>)}</div><div className={styles.structure}>{format.structure.map((item,index)=><span key={item}><b>{index+1}</b>{item}</span>)}</div></section>
      <section className={`${styles.panel} ${styles.wide}`}><Title number="03" title="Research tín hiệu nội dung" text="Nguồn tham chiếu là demand signal, không phải nội dung để sao chép."/><div className={extra.researchHead}><div><strong>{brand.niche}</strong><span>Từ khóa mở rộng: {domain.researchSeeds.join(" · ")}</span></div><button className={styles.primary} onClick={runResearch} disabled={!!busy}><Icon name="search"/> {busy==="research"?"Đang quét...":"Quét nội dung"}</button></div>{trends.length?<div className={extra.trendGrid}>{trends.map(item=><button key={item.id} className={selectedTrend?.id===item.id?styles.selected:""} aria-pressed={selectedTrend?.id===item.id} onClick={()=>chooseTrend(item)}><small>{item.angle||"Tín hiệu breakout"}</small><strong>{item.title}</strong><span>{item.channel} · {Number(item.views||0).toLocaleString("vi-VN")} views · {item.breakout||0}×</span></button>)}</div>:<div className={extra.empty}>Bấm “Quét nội dung” để lấy danh sách tín hiệu phù hợp với domain.</div>}{selectedTrend&&<label className={extra.approval}><input type="checkbox" checked={approvals.researchApproved} onChange={e=>setApprovals(prev=>({...prev,researchApproved:e.target.checked}))}/><span><strong>Duyệt nguồn research này</strong><small>Tôi chỉ dùng cấu trúc và tín hiệu nhu cầu, không sao chép câu chữ.</small></span></label>}</section>
      <section className={`${styles.panel} ${styles.wide}`}><Title number="04" title="Kịch bản & creative brief" text="Mỗi lần tạo trả về đúng ba góc khác nhau để bạn chọn."/><div className={extra.scriptAction}><span>{selectedTrend?`Đang bám tín hiệu: ${selectedTrend.title}`:"Chưa chọn nguồn research"}</span><button className={styles.primary} onClick={writeScript} disabled={!!busy||!selectedTrend}>{busy==="script"?"Đang viết...":"Tạo 3 kịch bản theo ngách"}</button></div>{scriptCandidates.length>0&&<div className={extra.candidateGrid}>{scriptCandidates.map(item=><button key={item.id} aria-pressed={script.id===item.id} className={script.id===item.id?styles.selected:""} onClick={()=>{setScript(item);setApprovals(prev=>({...prev,scriptApproved:false}));setJob(null);}}><small>{item.angle}</small><strong>{item.hook}</strong></button>)}</div>}<div className={styles.scriptGrid}><ScriptField label="Hook" value={script.hook} onChange={value=>updateScript("hook",value)} rows="2"/><ScriptField label="Body" value={script.body} onChange={value=>updateScript("body",value)} rows="6"/><ScriptField label="CTA" value={script.cta} onChange={value=>updateScript("cta",value)} rows="2"/></div><label className={extra.approval}><input type="checkbox" checked={approvals.scriptApproved} onChange={e=>setApprovals(prev=>({...prev,scriptApproved:e.target.checked}))}/><span><strong>Duyệt kịch bản hiện tại</strong><small>Tôi đã đọc nội dung, claim và disclaimer theo ngành.</small></span></label></section>
      <section className={`${styles.panel} ${styles.wide}`}><Title number="05" title="Production route & edit style" text="Chọn nguồn hình và một visual grammar chính cho toàn video."/><div className={styles.routes}>{[["avatar","AI Avatar","HeyGen + voice alignment"],["noface","No-face","Voice + visual proof"],["upload","Raw footage","Jump-cut + captions"]].map(([id,name,desc])=><button key={id} aria-pressed={videoMode===id} className={videoMode===id?styles.selected:""} onClick={()=>{setVideoMode(id);setJob(null);}}><strong>{name}</strong><span>{desc}</span></button>)}</div><div className={styles.styleGrid}>{editStyles.map(item=><button key={item.id} aria-pressed={styleId===item.id} className={styleId===item.id?styles.selected:""} onClick={()=>{setStyleId(item.id);setJob(null);}}><div>{item.palette.map(color=><i key={color} style={{background:color}}/>)}</div><strong>{item.name}{recommended.includes(item.id)&&<small>Đề xuất</small>}</strong><span>{item.bestFor}</span><p>{item.description}</p></button>)}</div><div className={styles.actions}><button className={styles.primary} onClick={buildManifest} disabled={!!busy||!approvals.researchApproved||!approvals.scriptApproved}>{busy==="manifest"?"Đang tạo...":"Tạo production manifest"}</button><button className={styles.secondary} onClick={downloadManifest} disabled={!job}><Icon name="download"/> Tải manifest</button></div>{job&&<div className={styles.job}><Icon name="check"/><div><strong>{job.jobId} · Manifest v2.0</strong><span>Hai checkpoint đầu đã duyệt · Render trả phí và publishing vẫn khóa</span></div></div>}</section>
    </div>
  </main>;
}

function Title({number,title,text}){return <div className={styles.title}><span>{number}</span><div><h2>{title}</h2><p>{text}</p></div></div>;}
function Field({label,value,onChange,textarea=false}){return <label>{label}{textarea?<textarea rows="2" value={value} onChange={e=>onChange(e.target.value)}/>:<input value={value} onChange={e=>onChange(e.target.value)}/>}</label>;}
function ScriptField({label,value,onChange,rows}){return <label>{label}<textarea rows={rows} value={value} onChange={e=>onChange(e.target.value)}/></label>;}
